#include "team04_race/lidar_planner.hpp"
#include <cmath>
#include <algorithm>
#include <iostream>
#include <stdexcept>
std::vector<team04::Point> scene(double offset=0,double curve=0,bool right=true){std::vector<team04::Point> p;for(double x=-2.6;x<=2.6;x+=.1)for(double y=-1;y<=1;y+=.1)if(std::hypot(x,y)>.35)p.push_back({x,y,-.13});for(double x=-2;x<12;x+=.01)for(double z=.04;z<.31;z+=.04){p.push_back({x,offset+curve*x*x+1.2,z-.13});if(right)p.push_back({x,offset+curve*x*x-1.2,z-.13});}return p;}
void check(bool ok,const char*name){if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<name<<'\n';}
int main(){team04::PlannerConfig c;c.max_speed=3;auto p=scene();auto a=team04::planLidar(p,c,2),b=team04::planCenterlineLidar(p,c,2);check(a.valid && a.speed==b.speed && a.steering==b.steering && a.path.size()==b.path.size(),"legacy mode preserves speed steering and path");c.path_mode="racing_line";c.planning_horizon=8;auto straight=team04::planLidar(p,c,2);check(straight.valid && !straight.racing_selected && std::abs(straight.steering)<.02,"straight racing mode retains certified center");check(straight.candidate_count==27 && straight.speed_profile.size()==straight.path.size(),"candidate and velocity profiles available");check(straight.speed*straight.speed/(2*c.braking)+straight.speed*c.reaction_time+.45<=straight.free_distance+.01,"observed stopping distance includes sensor reaction");check(!team04::planLidar(scene(0,0,false),c,2).valid,"racing mode rejects unseen boundary");check(!team04::planLidar({},c,2).valid,"racing mode rejects empty input");auto left=team04::planLidar(scene(0,.03),c,1);check(left.valid && left.steering<0,"racing left bend uses official negative steering");auto right=team04::planLidar(scene(0,-.03),c,1);check(right.valid && right.steering>0,"racing right bend uses official positive steering");c.braking=1.5;c.planning_horizon=2.5;auto shortView=team04::planLidar(p,c,1.2);check(shortView.valid && shortView.effective_lookahead>=1 && shortView.effective_lookahead<1.72,"short measured corridor adapts target above minimum");auto tooFast=team04::planLidar(p,c,3);check(!tooFast.valid && tooFast.reason=="INSUFFICIENT_STOPPING_DISTANCE","current command cannot exceed observed stopping distance");
 auto sparse=scene();sparse.erase(std::remove_if(sparse.begin(),sparse.end(),[](const team04::Point&q){return q.y<-.5 && q.x>3.5 && q.x<4.2 && q.z>-.1;}),sparse.end());c.planning_horizon=8;auto oldSparse=team04::planCenterlineLidar(sparse,c,1);auto measuredSparse=team04::planObservedCorridorLidar(sparse,c,1);check(measuredSparse.valid && measuredSparse.observed_sparse_links>0 && measuredSparse.free_distance>oldSparse.free_distance+.5,"sparse measured collinear wall endpoints extend certified corridor");
 auto discontinuous=scene();discontinuous.erase(std::remove_if(discontinuous.begin(),discontinuous.end(),[](const team04::Point&q){return q.y<-.5 && q.x>3.5 && q.x<4.2 && q.z>-.1;}),discontinuous.end());for(auto&q:discontinuous)if(q.y<-.5 && q.x>=4.2 && q.z>-.1)q.y-=1.4;auto rejected=team04::planObservedCorridorLidar(discontinuous,c,1);double rejectedRight=-100;for(const auto&q:rejected.right)rejectedRight=std::max(rejectedRight,q.x);check(rejectedRight<4.2,"wall identity cannot bridge a lateral discontinuity");
 auto ended=scene();ended.erase(std::remove_if(ended.begin(),ended.end(),[](const team04::Point&q){return q.y<-.5 && q.x>3.5 && q.z>-.1;}),ended.end());auto ending=team04::planObservedCorridorLidar(ended,c,1);double lastRight=-100;for(const auto&q:ending.right)lastRight=std::max(lastRight,q.x);check(lastRight<=3.51,"unobserved wall end is never extrapolated");
 check(straight.min_clearance>=c.safety_margin,"full envelope retains boundary margin");}
